from itertools import combinations

def find_all_X_Y(n):
    solutions = []
    # X_1 = 0, X_n <= (n^2-1)/2
    # Y_1 = 0, Y_n = (n^2-1) - X_n
    # For n=3, n^2-1 = 8. X_3 <= 4.
    # Let's try all X such that 0 = X_1 < X_2 < ... < X_n <= (n^2-1)//2.
    # Then find all Y such that 0 = Y_1 < Y_2 < ... < Y_n = (n^2-1) - X_n
    # and {X_i + Y_j} = {0, ..., n^2-1}.

    for X in combinations(range(n*n), n):
        if X[0] != 0: continue
        X_n = X[-1]
        if X_n > (n*n - 1) // 2: continue

        Y_n = (n*n - 1) - X_n
        # Find all Y such that Y_1=0, Y_n=Y_n and {X_i + Y_j} = {0, ..., n^2-1}
        # Y_j must be in {0, ..., Y_n}
        # Since n is small, we can use combinations.
        for Y in combinations(range(Y_n + 1), n):
            if Y[0] == 0 and Y[-1] == Y_n:
                # Check if {X_i + Y_j} = {0, ..., n^2-1}
                sums = set()
                for x in X:
                    for y in Y:
                        sums.add(x + y)
                if len(sums) == n*n and max(sums) == n*n - 1:
                    solutions.append((X, Y))
    return solutions

