def count_good_arrangements(n):
    # A matrix A is good if there exist x_i, y_j such that a_ij = x_i + y_j.
    # This is equivalent to saying that the set of values {a_ij} is X+Y
    # for some sets X, Y of size n.
    # And the problem says the set of values {a_ij} must be {1, ..., n^2}.
    # We found that X, Y must be {c, c+1, ..., c+n-1} and {d, d+n, ..., d+n(n-1)}
    # with c+d=1.
    # This means the matrix elements are a_ij = 1 + \alpha_i + \beta_j
    # where \alpha_i is a permutation of {0, 1, ..., n-1}
    # and \beta_j is a permutation of {0, n, 2n, ..., n(n-1)}.
    # OR \alpha_i is a permutation of {0, n, 2n, ..., n(n-1)}
    # and \beta_j is a permutation of {0, 1, ..., n-1}.

    # Let's find the number of such matrices.
    # Case 1: \alpha \in S1, \beta \in S2
    # Case 2: \alpha \in S2, \beta \in S1
    # where S1 = {0, 1, ..., n-1} and S2 = {0, n, 2n, ..., n(n-1)}.

    S1 = list(range(n))
    S2 = [i * n for i in range(n)]

    matrices = set()

    # Case 1
    import itertools
    for p1 in itertools.permutations(S1):
        for p2 in itertools.permutations(S2):
            matrix = []
            for i in range(n):
                row = []
                for j in range(n):
                    row.append(1 + p1[i] + p2[j])
                matrix.append(tuple(row))
            matrices.add(tuple(matrix))

    # Case 2
    for p1 in itertools.permutations(S2):
        for p2 in itertools.permutations(S1):
            matrix = []
            for i in range(n):
                row = []
                for j in range(n):
                    row.append(1 + p1[i] + p2[j])
                matrix.append(tuple(row))
            matrices.add(tuple(matrix))

    return len(matrices)

